// Atkinson 增强六色 LUT（修正表 + 选色表，自动生成，请勿手改）
// correction: 786432 B, selection: 262144 B
var AE_CORRECTION_LUT_B64 = "";
var AE_SELECTION_LUT_B64 = "";

var _aeLutReady = false;
var _aeCorrectionLUT = null;
var _aeSelectionLUT = null;
(function() {
    try {
        var corrBin = atob(AE_CORRECTION_LUT_B64);
        var selBin = atob(AE_SELECTION_LUT_B64);
        if (corrBin.length !== 786432 || selBin.length !== 262144) {
            throw new Error('LUT 长度校验失败');
        }
        _aeCorrectionLUT = new Uint8Array(786432);
        _aeSelectionLUT = new Uint8Array(262144);
        for (var i = 0; i < 786432; i++) _aeCorrectionLUT[i] = corrBin.charCodeAt(i);
        for (var i = 0; i < 262144; i++) _aeSelectionLUT[i] = selBin.charCodeAt(i);
        _aeLutReady = true;
    } catch (e) {
        console.warn('[Atkinson增强] LUT 解码失败，蓝/青区域将回退到 CIELAB 最近色: ' + e.message);
    }
})();
